#pragma once
#include "ksStateFieldService.h"
namespace ks {
// One real packed-map cursor half, retained across the router's restored
// count/part word. No CPU bank or completion ABI is created or consumed.
struct FieldParameterContextUpperTransfer final{bool known=false;uint16_t value=0;void then(FieldParameterContextUpperTransfer t){if(t.known)*this=t;}uint16_t apply(uint16_t prior)const{return known?value:prior;}};
namespace fieldParameterContextBindings {
using X=FieldParameterContextUpperTransfer;using K=StateFieldService::Kind;using F=StateFieldActionsTask;
inline X full(uint32_t p){return{true,uint16_t(p>>16)};}
inline X displayed(const StateScreenService::DisplayResult&r){if(!r.observed)return{};using P=StateDisplayService::Presentation;if(r.presentation==P::Table)return full(r.tableAfterHeader);if((r.presentation==P::Number||r.presentation==P::Text||r.presentation==P::Disabled)&&r.kind==StateDisplayService::Kind::Format&&r.input.type==47)return full(r.patch);return{};}
inline X value(const StateScreenService::ValueResult&r){if(!r.observed)return{};X out{true,0};if(r.type)out.then(displayed(r.current==r.reference?r.matchDisplay:r.referenceDisplay));return out;}
template<class V>X ui(const V&,unsigned=0);template<class V>X fieldRoot(const V&,unsigned=0);
template<class V>X label(const V&v){if(!v.summary().label)throw std::logic_error("Missing packed field label context");const auto&f=v.summary().label->facts;X out;if(f.modulationWord)out=full(f.modulationWord);if(f.sourceCopied||f.envelopeCopied)out={true,0};return out;}
template<class V>X sceneNode(const V&v,const StateSceneCoordinator::Summary&s,unsigned n,unsigned depth){if(depth>64||n>=s.count)throw std::logic_error("Packed field scene context depth");using C=StateSceneCoordinator::Kind;const auto&o=s.calls[n];const auto&f=o.facts;X out;const auto child=[&](C k){for(unsigned j=0;j<o.childCount;++j)if(s.calls[o.children[j]].kind==k){out.then(sceneNode(v,s,o.children[j],depth+1));return;}};
 if(o.kind==C::Bank||o.kind==C::Map)return out;if(o.kind==C::Load)return full(0x1748e);if(o.kind==C::Backup||o.kind==C::Copy)return full(0x1738e);if(o.kind==C::Restore)return f.previous?full(f.patch):out;if(o.kind==C::Activate){if(f.bank){child(C::Load);child(C::Apply);}return out;}if(o.kind==C::Apply){out=full(f.patch);child(C::Notify);return out;}if(o.kind==C::Notify){if(f.voice){const auto*p=v.lastVoice();if(!p||!p->global())throw std::logic_error("Missing packed field voice context");const auto*g=p->global();const auto&r=g->summary();if(!r.effect)out={true,0x8000};else{out=full(r.effect->second());if(const auto*d=g->lastDspService())if(d->summary().wordTransmitted)out={true,uint16_t(d->summary().word>>8)};}}return out;}
 if(o.kind==C::Knob){if(f.knobMagnitude<4||f.lock)return out;if(f.knobMode){if(!f.bank&&f.ui)out.then(ui(v,depth+1));return out;}}if(f.bank==f.oldBank)return out;if(!f.bank){child(C::Restore);child(C::Notify);if(f.ui)out.then(ui(v,depth+1));return out;}if(!f.oldBank)child(C::Map);if(!f.mode){child(C::Restore);child(C::Activate);}if(f.ui)out.then(ui(v,depth+1));return out;
}
template<class V>X scene(const V&view,unsigned depth){const auto v=view.sceneView();const auto*p=v.sceneRootSummary();if(!p)throw std::logic_error("Missing packed field scene root");return sceneNode(v,*p,0,depth+1);}
template<class V>X field(F::Kind k,const V&v,unsigned depth){if(depth>64)throw std::logic_error("Packed field context depth");const auto&p=v.summary().fields[unsigned(k)];if(!p)throw std::logic_error("Missing packed field context outcome");const auto&o=*p;X out;if(k==F::Kind::Return||k==F::Kind::Control||k==F::Kind::Cycle||k==F::Kind::Current)return out;if(k==F::Kind::Clear)return ui(v,depth+1);
 if(k==F::Kind::DirectStep||k==F::Kind::IndexedStep){if(v.summary().address)out=full(v.summary().address->task.target());out.then(field(F::Kind::Current,v,depth+1));if(k==F::Kind::DirectStep){out=full(o.input.pointer-o.task.patch());if(uint8_t(o.input.pointer-o.task.patch())==225&&v.lastPacket())out={true,0};}return out;}if(k==F::Kind::Bit||k==F::Kind::Pair){if(v.summary().address)out=full(v.summary().address->task.target());return out;}
 if(k==F::Kind::Global||k==F::Kind::Selector||k==F::Kind::Indexed){if(k==F::Kind::Global)out=full(0x168fc);if(v.summary().address)out=full(v.summary().address->task.target());if(v.summary().bounds)out=full(v.summary().bounds->task.pointer());const bool zero=(o.input.mode>>8)&&!uint8_t(v.summary().bounds->task.value());if(zero&&(uint8_t(o.input.mode)==1||uint8_t(o.input.mode)==14))return out;if(!o.task.enabled())return out;out=full(o.input.pointer-o.task.base());out.then(label(v));if(const auto*p=v.lastScreen())out.then(value(p->value));return out;}throw std::logic_error("Unknown packed field context kind");}
template<class V>X fieldRoot(const V&v,unsigned depth){if(depth>64)throw std::logic_error("Packed field root context depth");const auto k=v.kind();const auto&s=v.summary();if(k>=K::IndexedAddress&&k<=K::GlobalAddress)return full(s.address->task.target());if(k==K::Bounds)return full(s.bounds->task.pointer());if(k==K::Label)return label(v);if(k==K::EditActive||k==K::Return)return{};if(k==K::Publish)return s.published?X{true,0}:X{};if(k==K::Velocity||k==K::ApplyVelocity){const auto h=uint8_t(v.input().event>>8);return{true,uint16_t(unsigned(h)*h*2)};}if(k>=K::Global&&k<=K::Control)return field(F::Kind(unsigned(k)-unsigned(K::Global)),v,depth+1);if(k==K::DirectEdit&&!uint8_t(v.input().event>>8))return{};const auto*w=s.editWorkflow?&*s.editWorkflow:s.workflow?&*s.workflow:nullptr;if(!w)throw std::logic_error("Missing packed field workflow");X out=full(v.handlerBinding());const auto c=w->result.category;if(c==8)out.then(scene(v,depth+1));else if(c==1){const auto h=uint8_t(w->input.event>>8);out={true,uint16_t(unsigned(h)*h*2)};}else out.then(field(c==0?F::Kind::Indexed:c==2?F::Kind::DirectStep:c==3?F::Kind::IndexedStep:c==4?F::Kind::Pair:c==5?F::Kind::Selector:c==6?F::Kind::Bit:F::Kind::Global,v,depth+1));return out;}
inline X rowDisplay(const StateUiRefreshService::Presentation&r){using P=StateDisplayService::Presentation;if(!r.observed)return{};if(r.form==P::Table)return full(r.tableAfterHeader);if((r.form==P::Number||r.form==P::Text||r.form==P::Disabled)&&r.kind==StateDisplayService::Kind::Format&&r.input.type==47)return full(r.patch);return{};}
template<class V>X ui(const V&v,unsigned depth){if(depth>64)throw std::logic_error("Packed field UI context depth");const auto*r=v.lastRefresh();if(!r)throw std::logic_error("Missing packed field UI outcome");X out;if(r->automaticIndex!=~0u)out=fieldRoot(v.completedView(r->automaticIndex),depth+1);else if(r->rendered){const auto*p=v.lastScreen();if(!p)throw std::logic_error("Missing packed field render outcome");out={true,0};out.then(value(p->value));}if(r->nameRead)out=full(0x1734c);if(r->headingObserved)out=full(r->heading);if(r->partsShown)out=full(0x167b8);if(r->specialShown&&r->specialMessage){for(unsigned n=0;n<4;++n){const auto&row=r->row[n];out=full(row.program);if(row.bank){out=full(row.lookup);out.then(rowDisplay(row.display));}}}return out;}
}
inline FieldParameterContextUpperTransfer fieldUiParameterContextUpperTransfer(const StateFieldService&s){if(!s.complete())throw std::logic_error("Incomplete packed field UI context");return fieldParameterContextBindings::ui(s.projectionView());}
inline uint16_t fieldUiParameterContextUpperAfter(const StateFieldService&s,uint16_t prior){return fieldUiParameterContextUpperTransfer(s).apply(prior);}
inline FieldParameterContextUpperTransfer fieldParameterContextUpperTransfer(const StateFieldService&s){if(!s.complete())throw std::logic_error("Incomplete packed field context");return fieldParameterContextBindings::fieldRoot(s.projectionView());}
inline uint16_t fieldParameterContextUpperAfter(const StateFieldService&s,uint16_t prior){return fieldParameterContextUpperTransfer(s).apply(prior);}
}
